const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',face:'<path d="M8 3H5a2 2 0 0 0-2 2v3m13-5h3a2 2 0 0 1 2 2v3M3 16v3a2 2 0 0 0 2 2h3m13-5v3a2 2 0 0 1-2 2h-3M8 9v2m8-2v2m-7 5c2 1.5 4 1.5 6 0m-3-7v5h-2"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',settings:'<path d="m9 3-.5 3-2.5 1-2.5-1.2-2 3.4L4 11v2l-2.5 1.8 2 3.4L6 17l2.5 1 .5 3h4l.5-3 2.5-1 2.5 1.2 2-3.4L18 13v-2l2.5-1.8-2-3.4L16 7l-2.5-1-.5-3Z"/><circle cx="11" cy="12" r="3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z"/><path d="m8 12 3 3 5-6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8.5a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4M12 16h.01"/>',activity:'<path d="M2 12h4l3-8 6 16 3-8h4"/>',camera:'<path d="M4 6h4l2-3h4l2 3h4v15H4Z"/><circle cx="12" cy="13" r="4"/>',link:'<path d="m10 13 4-4m-6 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 2 2-2a4 4 0 1 1 6 6l-5 5a4 4 0 0 1-6 0"/>'};
const icon=(name,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.face}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes={overview:['Visão geral','overview'],verify:['Verificação 1:1','face'],identities:['Identidades','users'],vision:['Visão computacional','activity'],api:['API & documentação','code'],settings:['Configurações','settings']};
const sample=[{id:'vrf_8f2a91',name:'Mariana Costa',subject:'colab_001',status:'approved',date:'Hoje, 14:32:08',ms:842,initials:'MC'},{id:'vrf_7c4b28',name:'Pedro Almeida',subject:'colab_002',status:'approved',date:'Hoje, 14:28:45',ms:916,initials:'PA'},{id:'vrf_6e9d13',name:'Juliana Santos',subject:'colab_003',status:'liveness_failed',date:'Hoje, 14:25:12',ms:1204,initials:'JS'},{id:'vrf_5a1c74',name:'Lucas Ferreira',subject:'colab_004',status:'approved',date:'Hoje, 14:21:56',ms:789,initials:'LF'},{id:'vrf_4b8e02',name:'Camila Oliveira',subject:'colab_005',status:'face_mismatch',date:'Hoje, 14:18:30',ms:1056,initials:'CO'}];
let records=[...sample],identities=sample.map(x=>({id:x.subject,name:x.name,initials:x.initials}));
let base='',token='',connected=false,route='',stream=null,recording=false,endpoint=0,activeSession=null;
let sessionGeneration=0;
let toastTimer;
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4500)}
function goto(r){if(recording)return toast('Aguarde o fim da captura antes de navegar.');location.hash=r;if(route===r)render()}
function title(name,desc,buttons=''){return `<div class="page-title"><div><h1>${name}</h1><p>${desc}</p></div><div class="actions">${buttons}</div></div>`}
function banner(){return `<div class="demo-banner">${icon('shield',15)}<span><strong>${connected?'Backend conectado.':'Ambiente de demonstração.'}</strong> ${connected?'Indicadores e identidades são exemplos; atualize os eventos pela API.':'Dados sintéticos para explorar a plataforma.'}</span><button data-route="settings">${connected?'Ver conexão':'Conectar API'}</button></div>`}
function status(s){let label={approved:'Aprovada',liveness_failed:'Prova de vida falhou',face_mismatch:'Não corresponde',review_required:'Revisão necessária'}[s]||s;return `<span class="status ${s==='approved'?'':s==='review_required'?'pending':'failed'}">${esc(label)}</span>`}
async function request(path,method='GET',body){if(!base)throw Error('Conecte o backend em Configurações.');let opts={method,headers:{Authorization:'Bearer '+token}};if(body instanceof FormData)opts.body=body;else if(body){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}const res=await fetch(base+path,opts);if(res.status===204)return {};const out=await res.json();if(!res.ok)throw Error(typeof out.detail==='string'?out.detail:JSON.stringify(out.detail||out));return out}
function table(rows=records){return `<div class="table-scroll"><table><thead><tr><th>IDENTIDADE</th><th>VERIFICAÇÃO</th><th>RESULTADO</th><th>DATA E HORA</th><th>TEMPO</th><th></th></tr></thead><tbody id="record-rows">${rowsHTML(rows)}</tbody></table></div>`}
function rowsHTML(rows){return rows.length?rows.map(x=>`<tr><td><div class="person"><span class="avatar">${esc(x.initials)}</span><div><b>${esc(x.name)}</b><small>${esc(x.subject)}</small></div></div></td><td class="mono">${esc(x.id)}</td><td>${status(x.status)}</td><td>${esc(x.date)}</td><td class="mono">${esc(x.ms)} ms</td><td><button class="row-detail" data-detail="${esc(x.id)}" aria-label="Ver detalhes de ${esc(x.name)}">${icon('arrow',14)}</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhuma verificação encontrada.</td></tr>'}
function chart(days=7){const vals=days===7?[53,46,64,52,94,76,67,114,90,126,95,117,102,151,131,158]:[47,82,55,103,74,123,98,139,112,161,143,174,155,196,172,211];let points=vals.map((v,i)=>`${49+i*31},${194-v*.8}`).join(' ');return `<svg class="chart" viewBox="0 0 550 220" role="img" aria-label="Gráfico ilustrativo de verificações sintéticas ao longo de ${days} dias"><g><line x1="49" y1="30" x2="520" y2="30"/><line x1="49" y1="80" x2="520" y2="80"/><line x1="49" y1="130" x2="520" y2="130"/><line x1="49" y1="180" x2="520" y2="180"/></g><text x="14" y="34">150</text><text x="14" y="84">100</text><text x="20" y="134">50</text><text x="26" y="184">0</text><path class="chart-area" d="M49 180 L${points.replaceAll(' ',' L')} L514 180 Z"/><path class="secondary" d="M49 164 80 159 111 169 142 155 173 160 204 153 235 164 266 147 297 157 328 148 359 159 390 145 421 153 452 140 483 150 514 142"/><polyline points="${points}" fill="none" stroke="#368367" stroke-width="2.5" stroke-linejoin="round"/><g><text x="43" y="208">${days===7?'Seg':'01 nov'}</text><text x="120" y="208">${days===7?'Ter':'06 nov'}</text><text x="197" y="208">${days===7?'Qua':'11 nov'}</text><text x="274" y="208">${days===7?'Qui':'16 nov'}</text><text x="350" y="208">${days===7?'Sex':'21 nov'}</text><text x="427" y="208">${days===7?'Sáb':'26 nov'}</text><text x="500" y="208">${days===7?'Dom':'30 nov'}</text></g></svg>`}
function overview(){return title('Visão geral','Uma visão clara de cada verificação. Um acesso mais seguro.',`<button class="btn" id="export">${icon('download')}Exportar dados</button><button class="btn primary" data-route="verify">${icon('plus')}Nova verificação</button>`)+banner()+`<section class="stats" aria-label="Métricas ilustrativas"><article class="stat"><div class="stat-top">Verificações realizadas ${icon('face')}</div><div class="stat-value">1.284</div><div class="stat-bottom"><b>↗ 12,8%</b> vs. período anterior</div></article><article class="stat"><div class="stat-top">Taxa de aprovação ${icon('shield')}</div><div class="stat-value">98,2<span style="font-size:20px">%</span></div><div class="stat-bottom"><b>↗ 2,4%</b> vs. período anterior</div></article><article class="stat"><div class="stat-top">Tempo médio ${icon('clock')}</div><div class="stat-value">842 <span style="font-size:17px;color:#7d8a81;font-weight:450">ms</span></div><div class="stat-bottom">Exemplo de tempo de resposta</div></article><article class="stat"><div class="stat-top">Revisões necessárias ${icon('activity')}</div><div class="stat-value">23</div><div class="stat-bottom"><b class="warning">1,8% do total</b> valores ilustrativos</div></article></section><section class="dashboard-grid"><article class="panel"><div class="panel-head"><div><h2>Atividade de verificações</h2><p>Volume de solicitações ao longo do tempo</p></div><select class="select" id="chart-period" aria-label="Período do gráfico"><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option></select></div><div class="chart-legend"><span><i class="legend-dot"></i>Aprovadas</span><span><i class="legend-dot gray"></i>Revisões</span></div><div id="chart-area">${chart()}</div><div class="chart-foot"><span>Dados de demonstração</span><b>Verificação facial 1:1</b></div></article><article class="panel quick-panel"><div class="scan-symbol">${icon('face')}</div><h2>Uma pessoa.<br>Uma identidade.</h2><p>Compare um rosto com uma referência e acompanhe a prova de vida em um único fluxo.</p><button class="btn primary" data-route="verify">Testar verificação 1:1 ${icon('arrow',16)}</button><small>Conheça o fluxo antes de integrar</small></article></section><section class="panel"><div class="table-head"><div><h2>Verificações recentes</h2><p>Últimas solicitações no seu workspace</p></div><div class="table-tools"><div class="input-search">${icon('search',13)}<input id="search-records" placeholder="Buscar identidade..." aria-label="Buscar identidade"></div><select id="status-filter" class="select" aria-label="Filtrar resultado"><option value="all">Todos os resultados</option><option value="approved">Aprovadas</option><option value="failed">Revisões e falhas</option></select></div></div>${table()}<div class="table-footer"><span id="row-count">${records.length} verificações · ${records.some(x=>x.source==='api')?'eventos da API':'dados sintéticos'}</span><button class="link-button" id="refresh-events">${connected?'Atualizar da API':'Explorar a API'} ${icon('arrow',13)}</button></div></section><div class="health-row"><span><i class="small-dot"></i>Console disponível</span><span>Motor facial: ${connected?'consultar API':'não conectado'}</span><span>Prova de vida: experimental</span><span class="health-right">Python + FastAPI <span class="footer-dot">·</span> API v1</span></div>`}
function verification(){return title('Verificação facial 1:1','Confirme se a pessoa diante da câmera corresponde à identidade informada.',`<button class="btn" data-route="api">${icon('code')}Ver integração</button>`)+banner()+`<div class="steps"><div class="step active"><span>1</span>Identidade</div><div class="step-line"></div><div class="step"><span>2</span>Captura e prova de vida</div><div class="step-line"></div><div class="step"><span>3</span>Resultado</div></div><div class="verify-grid"><section class="panel"><div class="camera"><span class="camera-badge" id="camera-badge">CÂMERA DESLIGADA</span><video id="camera-video" autoplay muted playsinline class="hidden"></video><div class="camera-frame">${icon('face')}</div><p id="camera-instruction">Posicione seu rosto dentro da área indicada</p></div><div class="camera-tools"><p>Vídeo de 5 segundos<br>Até 8 MiB · sem áudio</p><div class="actions"><button class="btn" id="camera-toggle">${icon('camera')}Ativar câmera</button><button class="btn primary" id="capture" disabled>Gravar e verificar</button></div></div><div id="verify-result" class="result-box hidden"></div></section><aside class="panel pad-panel"><h2>Dados da verificação</h2><label>Identificador da pessoa<input id="verify-subject" placeholder="Ex.: colab_001" value="colab_001" maxlength="128"></label><label class="check"><input type="checkbox" id="verify-consent"> A pessoa autorizou a captura e o uso da biometria para esta finalidade.</label><button class="btn primary full" id="create-session">${icon('plus')}Criar sessão de verificação</button><p class="api-status" id="session-status">${connected?'Conectado. Crie uma sessão antes de gravar.':'Conecte sua API para realizar uma verificação real.'}</p><hr class="separator"><h2>Prova de vida ativa</h2><div class="info-row"><span>Desafio</span><b>Movimentos aleatórios</b></div><div class="info-row"><span>Sessão</span><b>Uso único · 120 segundos</b></div><div class="info-row"><span>Comparação</span><b>1 referência × 1 rosto</b></div><div class="note">O motor próprio analisa movimentos e objetos. Nesta versão experimental, o resultado exige revisão e não deve liberar um registro de ponto automaticamente.</div><hr class="separator"><button class="btn full" id="simulate">Explorar resultado de demonstração ${icon('arrow',15)}</button></aside></div>`}
function identitiesPage(){return title('Identidades','Referências individuais para comparação facial. Sem busca entre pessoas.',`<button class="btn primary" id="add-identity">${icon('plus')}Cadastrar identidade</button>`)+banner()+`<section class="panel"><div class="table-head"><div><h2>Referências cadastradas</h2><p>${connected?'Novos cadastros são enviados à API. A lista abaixo é demonstrativa.':'Cadastros de demonstração ficam apenas nesta sessão do navegador.'}</p></div><span class="status">${identities.length} identidades</span></div><div class="table-scroll"><table><thead><tr><th>PESSOA</th><th>IDENTIFICADOR</th><th>REFERÊNCIA</th><th>FINALIDADE</th><th></th></tr></thead><tbody>${identities.map(x=>`<tr><td><div class="person"><span class="avatar">${esc(x.initials)}</span><b>${esc(x.name)}</b></div></td><td class="mono">${esc(x.id)}</td><td><span class="status">${x.real?'Cadastrada na API':'Demonstrativa'}</span></td><td>Validação de identidade</td><td><button class="link-button" data-remove="${esc(x.id)}">Excluir referência</button></td></tr>`).join('')}</tbody></table></div></section><div class="note margin-top">A referência facial não comprova, sozinha, a identidade civil. Em produção, o cadastro precisa de uma origem confiável e autorização adequada. A exclusão pela API remove o template e os eventos relacionados.</div>`}
const endpoints=[{method:'POST',path:'/api/v1/sessions',title:'Criar sessão',description:'Vincule a captura a uma identidade cadastrada. A sessão expira em 120 segundos e só pode ser consumida uma vez.',body:{subject_id:'colab_001',consent:true},response:{session_id:'sess_demonstracao',nonce:'nonce_aleatorio',expires_at:1794240000,max_bytes:8388608,max_duration_seconds:8,challenge:['turn_left','turn_right']}},{method:'POST',path:'/api/v1/subjects',title:'Cadastrar referência',description:'Cadastre exatamente um rosto por identidade, com consentimento. Envie multipart/form-data com subject_id, consent e reference (JPG ou PNG).',response:{subject_id:'colab_001',status:'enrolled'}},{method:'POST',path:'/api/v1/sessions/{id}/verify',title:'Verificar identidade',description:'Envie o nonce recebido e o vídeo como multipart/form-data. O servidor valida o desafio, chama o motor de prova de vida e compara o rosto com a referência.',response:{session_id:'sess_demonstracao',decision:'review_required',similarity:0.72,threshold:0.363,liveness:{live:true,score:0.81,validated:false},elapsed_ms:1260}},{method:'GET',path:'/api/v1/events',title:'Consultar eventos',description:'Liste até 100 eventos recentes. Os tempos e resultados são medidos pelo servidor.',response:{events:[]}},{method:'GET',path:'/api/v1/health',title:'Estado dos motores',description:'Consulte a disponibilidade do motor facial e da integração de prova de vida. Este endpoint não exige chave.',response:{status:'development',face_engine:'not_configured',liveness:'not_configured',version:'0.1.0'}},{method:'DELETE',path:'/api/v1/subjects/{id}',title:'Excluir referência',description:'Remova a referência, suas sessões e seus eventos. Esta operação não pode ser desfeita.',response:{status:204}}];
function codeFor(e){const origin=base||'http://localhost:8000';const slash=' \\\n';let command=`curl -X ${e.method} '${origin}${e.path}'`+slash+'  -H "Authorization: Bearer $VERIFICA_ADMIN_KEY"';if(e.body)command+=slash+"  -H 'Content-Type: application/json'"+slash+`  -d '${JSON.stringify(e.body)}'`;else if(e.method==='POST')command+=e.path.includes('verify')?slash+"  -F 'nonce=NONCE_DA_SESSAO'"+slash+"  -F 'video=@captura.webm'":slash+"  -F 'subject_id=colab_001'"+slash+"  -F 'consent=true'"+slash+"  -F 'reference=@referencia.jpg'";return command}
function apiPage(){const e=endpoints[endpoint];return title('API & documentação','Da primeira chamada à verificação completa. Uma integração direta.',`<a class="btn" href="./verifica-ai-source.zip" download>Baixar projeto</a><button class="btn" id="open-swagger">${icon('code')}OpenAPI / Swagger</button>`)+`<div class="api-grid"><aside class="panel api-menu"><h3>ENDPOINTS · v1</h3>${endpoints.map((x,i)=>`<button class="endpoint ${i===endpoint?'active':''}" data-endpoint="${i}"><span class="method ${x.method.toLowerCase()}">${x.method}</span>${x.title}</button>`).join('')}<button class="endpoint" data-route="architecture">${icon('code',15)}Por que Python?</button></aside><section class="panel api-body"><h2>${e.title}</h2><span class="mono"><b class="method">${e.method}</b> ${e.path}</span><p>${e.description}</p><div class="code-head"><span>cURL · autenticação Bearer</span><button id="copy-code">Copiar código</button></div><pre><code>${esc(codeFor(e))}</code></pre><h3>Resposta de exemplo</h3><div class="api-response">${esc(JSON.stringify(e.response,null,2))}</div><p class="form-note">Resposta ilustrativa. Similaridade não representa probabilidade de identidade.</p>${e.body?`<h3>Experimentar chamada</h3><label>Identificador<input id="playground-subject" value="colab_001"></label><button id="run-api" class="btn primary">${icon('arrow',15)}${connected?'Enviar para a API':'Simular requisição'}</button><div class="api-response margin-top hidden" id="playground-result"></div>`:''}<h3>Erros que sua integração deve tratar</h3><div class="table-scroll"><table><tbody><tr><td class="mono">401</td><td>Chave ausente ou inválida</td></tr><tr><td class="mono">409</td><td>Sessão expirada, usada ou cadastro duplicado</td></tr><tr><td class="mono">413 / 422</td><td>Captura excede o limite ou não atende à qualidade</td></tr><tr><td class="mono">503</td><td>Motor facial ou prova de vida não configurado</td></tr></tbody></table></div></section></div>`}
function settings(){return title('Configurações','Conecte a API e acompanhe os componentes da sua infraestrutura.')+`<div class="two-col"><section class="panel settings-panel"><h2>Conexão com o backend</h2><p>O console hospedado se conecta ao seu servidor Python via HTTPS. As credenciais ficam apenas na memória desta aba.</p><form id="connection-form"><label>URL base da API<input name="base" type="url" required placeholder="https://api.seu-dominio.com" value="${esc(base)}"></label><label>Chave administrativa<input name="token" type="password" required autocomplete="off" placeholder="Sua VERIFICA_ADMIN_KEY" value="${esc(token)}"></label><div class="actions"><button class="btn primary" type="submit">${icon('link',15)}Testar e conectar</button><button class="btn" type="button" id="disconnect">Desconectar</button></div><p class="api-status" id="connection-result">${connected?'Conexão ativa nesta aba.':'Nenhum backend conectado.'}</p></form><div class="note">Configure VERIFICA_ALLOWED_ORIGINS no servidor com a origem deste console. Nunca distribua a chave administrativa em um aplicativo público.</div></section><section class="panel settings-panel"><h2>Componentes do Verifica.ai</h2><p>Uma arquitetura que separa a interface, a identidade e a análise de vídeo.</p><ul class="feature-list"><li>${icon('check')}API · Python + FastAPI <small>Implementada</small></li><li>${icon('face')}Biometria · YuNet + SFace <small>Modelos locais</small></li><li>${icon('activity')}Ações · desafio de movimentos <small>Experimental</small></li><li>${icon('camera')}Objetos · MobileNet SSD <small>Modelo opcional</small></li><li>${icon('shield')}Proteção contra apresentação <small>Validar em campo</small></li></ul><button class="link-button" data-route="architecture">Ver avaliação das linguagens ${icon('arrow',14)}</button></section></div><section class="panel settings-panel margin-top"><h2>Como executar seu backend</h2><p>O código completo inclui API, serviço próprio de visão, testes e documentação. A API pode ser hospedada em uma máquina com CPU; GPU pode ser adicionada após medição.</p><div class="code-head"><span>Terminal · desenvolvimento</span></div><pre><code>python -m venv .venv
pip install -r requirements.txt
python -m backend.download_models
# Defina as chaves e as variáveis do arquivo .env.example
uvicorn backend.main:app --host 0.0.0.0 --port 8000</code></pre><p class="form-note">Consulte o README para iniciar também o serviço de liveness na porta 8001.</p></section>`}
function vision(){return title('Visão computacional','Rostos, objetos e ações em uma captura vinculada a um desafio.',`<button class="btn primary" data-route="verify">${icon('face')}Abrir captura</button>`)+`<div class="demo-banner">${icon('activity',15)}<span><strong>Motor próprio · experimental.</strong> Resultados exigem revisão até a validação ant fraude.</span></div><div class="two-col"><section class="panel settings-panel"><h2>O que o motor analisa</h2><p>O vídeo passa por etapas independentes. Detecção de objetos enriquece o contexto; ela não comprova prova de vida.</p><ul class="feature-list"><li>${icon('face')}Exatamente um rosto por captura<small>YuNet</small></li><li>${icon('activity')}Ordem dos movimentos solicitados<small>Desafio aleatório</small></li><li>${icon('camera')}Objetos presentes no ambiente<small>MobileNet SSD · 20 classes</small></li><li>${icon('shield')}Vínculo do resultado ao vídeo<small>SHA-256 + HMAC</small></li></ul><div class="note">Ações suportadas nesta versão: olhar ao centro e virar a cabeça para os dois lados. A análise usa a posição dos marcos faciais; não inclui detecção de piscadas.</div></section><section class="panel settings-panel"><h2>Um desafio diferente por sessão</h2><p>O servidor escolhe a sequência e mantém o desafio associado ao nonce. O cliente recebe as instruções, grava e envia o vídeo.</p><div class="action-list"><span class="action-tag">Olhe ao centro</span><span class="action-tag">Vire para a esquerda</span><span class="action-tag">Vire para a direita</span></div><hr class="separator"><h2>Próximos critérios de validação</h2><p>Medir ataques com foto impressa, tela, replay, máscaras e vídeos sintéticos; calibrar limiares e avaliar diferentes câmeras, iluminações e perfis de pessoas.</p><div class="info-row"><span>Uso inicial</span><b>Validação para ponto</b></div><div class="info-row"><span>Decisão automática</span><b>Bloqueada no modo experimental</b></div><div class="info-row"><span>Expansão</span><b>Autenticação e acesso</b></div></section></div>`}
function architecture(){return title('Uma base preparada para evoluir','Avaliação técnica para biometria facial, ações e detecção de objetos.',`<button class="btn" data-route="api">${icon('arrow')}Voltar à API</button>`)+`<section class="panel settings-panel"><h2>Python + FastAPI <span class="tag">Escolha para o Verifica.ai</span></h2><p>O custo dominante é a inferência dos modelos. Python permite integrar OpenCV, ONNX Runtime e ferramentas de treinamento com menos atrito. O processamento pesado roda em código nativo e em trabalhadores separados.</p><div class="table-scroll"><table class="tech-table"><thead><tr><th>LINGUAGEM</th><th>PONTOS FORTES</th><th>CUSTO PARA ESTE PROJETO</th><th>INDICAÇÃO</th></tr></thead><tbody><tr><td><b>Python</b></td><td>Ecossistema de visão, experimentação e treinamento</td><td>Exige limitar concorrência e separar inferência da API</td><td>API e motor de visão inicial</td></tr><tr><td><b>Go</b></td><td>Concorrência, serviços leves e distribuição simples</td><td>Mais integração para modelos e pré-processamento</td><td>Gateway de alto volume após medição</td></tr><tr><td><b>Rust</b></td><td>Controle de memória e latência previsível</td><td>Maior esforço de desenvolvimento e integração de visão</td><td>Agentes locais e componentes críticos</td></tr><tr><td><b>C#</b></td><td>ASP.NET Core, ONNX Runtime e integrações empresariais</td><td>Menor variedade de ferramentas de pesquisa e treino</td><td>Boa opção para equipes .NET</td></tr></tbody></table></div><h2 class="margin-top">Otimização antes de escalar</h2><p>Upload binário, vídeo curto e sem áudio; no máximo oito quadros na comparação 1:1; resolução reduzida para inferência; modelos carregados uma vez por processo; concorrência limitada. O serviço de ações usa amostragem temporal própria. Testes de carga e calibração ainda são necessários: não há promessa de latência ou precisão nesta versão.</p></section>`}
function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}
function render(){const next=location.hash.slice(1)||'overview';if(route==='verify'){sessionGeneration++;activeSession=null;if(next!==route)stopCamera();}route=next in routes||next==='architecture'?next:'overview';document.querySelector('#crumb').textContent=routes[route]?.[0]||'Arquitetura';document.querySelector('#nav').innerHTML=Object.entries(routes).map(([key,[label,i]])=>`<button data-route="${key}" class="nav-link ${route===key?'active':''}">${icon(i)}${label}${key==='api'?'<span class="badge">v1</span>':''}</button>`).join('');document.querySelector('#main').innerHTML=({overview,verify:verification,identities:identitiesPage,vision,api:apiPage,settings,architecture}[route])();bind();}
function filterRows(){const query=(document.querySelector('#search-records')?.value||'').toLowerCase();const f=document.querySelector('#status-filter')?.value||'all';const rows=records.filter(x=>(x.name+' '+x.subject+' '+x.id).toLowerCase().includes(query)&&(f==='all'||(f==='failed'?x.status!=='approved':x.status==='approved')));document.querySelector('#record-rows').innerHTML=rowsHTML(rows);document.querySelector('#row-count').textContent=`${rows.length} verificações · ${rows.some(x=>x.source==='api')?'eventos da API':'dados sintéticos'}`;}
function bind(){document.querySelector('#chart-period')?.addEventListener('change',e=>document.querySelector('#chart-area').innerHTML=chart(+e.target.value));document.querySelector('#search-records')?.addEventListener('input',filterRows);document.querySelector('#status-filter')?.addEventListener('change',filterRows);document.querySelector('#export')?.addEventListener('click',()=>{const csv='\uFEFFidentidade;identificador;resultado;tempo_ms;tipo\n'+records.map(x=>[x.name,x.subject,x.status,x.ms,x.source||'demonstracao'].join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='verifica-ai-verificacoes.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Exportação CSV concluída.')});document.querySelector('#refresh-events')?.addEventListener('click',async()=>{if(!connected)return goto('api');try{const out=await request('/api/v1/events');records=out.events.map(x=>({id:x.id,name:x.subject,subject:x.subject,status:x.status,date:new Date(x.created*1000).toLocaleString('pt-BR'),ms:x.elapsed,source:'api',backend:base,initials:x.subject.slice(0,2).toUpperCase()}));render();toast('Eventos atualizados da API.')}catch(e){toast(e.message)}});document.querySelector('#add-identity')?.addEventListener('click',()=>{document.querySelector('#identity-note').textContent=connected?'O arquivo é obrigatório e será enviado ao backend.':'Demonstração: o arquivo não será enviado nem armazenado.';document.querySelector('#identity-dialog').showModal()});document.querySelector('#camera-toggle')?.addEventListener('click',toggleCamera);document.querySelector('#create-session')?.addEventListener('click',createSession);document.querySelector('#capture')?.addEventListener('click',capture);for(const selector of ['#verify-subject','#verify-consent'])document.querySelector(selector)?.addEventListener('input',()=>{if(activeSession){activeSession=null;document.querySelector('#capture').disabled=true;document.querySelector('#session-status').textContent='Dados alterados. Crie uma nova sessão com a autorização atual.';document.querySelector('#camera-instruction').textContent='Crie uma nova sessão para receber o desafio.';document.querySelectorAll('.step').forEach((el,i)=>el.classList.toggle('active',i===0));}});document.querySelector('#simulate')?.addEventListener('click',()=>{showResult('Demonstração · revisão necessária','Rosto correspondente no exemplo. Desafio de movimentos concluído no exemplo. O motor experimental exige revisão humana; este resultado não valida uma pessoa real.');document.querySelectorAll('.step').forEach(x=>x.classList.add('active'))});document.querySelector('#copy-code')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(codeFor(endpoints[endpoint]));toast('Código copiado.')}catch{toast('Seu navegador bloqueou a cópia. Selecione o código e copie.')}});document.querySelector('#open-swagger')?.addEventListener('click',()=>{if(!base)return toast('Conecte o backend para acessar o Swagger.');window.open(base+'/docs','_blank','noopener,noreferrer')});document.querySelector('#run-api')?.addEventListener('click',async(e)=>{const out=document.querySelector('#playground-result');out.classList.remove('hidden');e.currentTarget.disabled=true;try{const subject=document.querySelector('#playground-subject').value;out.textContent=connected?JSON.stringify(await request('/api/v1/sessions','POST',{subject_id:subject,consent:true}),null,2):'SIMULAÇÃO — nenhuma requisição enviada\n'+JSON.stringify({...endpoints[0].response,subject_id:subject},null,2)}catch(err){out.textContent=err.message}finally{if(e.target.isConnected)e.target.disabled=false}});document.querySelector('#connection-form')?.addEventListener('submit',connect);document.querySelector('#disconnect')?.addEventListener('click',()=>{base='';token='';connected=false;activeSession=null;records=[...sample];identities=sample.map(x=>({id:x.subject,name:x.name,initials:x.initials}));render();toast('Backend desconectado. Credenciais removidas da memória.')});}
function showResult(title,text,error=false,technical=null){const el=document.querySelector('#verify-result');if(!el)return;el.classList.remove('hidden');el.innerHTML=`<strong class="${error?'error-text':''}">${esc(title)}</strong><p>${esc(text)}</p>${technical?`<details><summary>Detalhes técnicos</summary><pre>${esc(JSON.stringify(technical,null,2))}</pre></details>`:''}`}
async function toggleCamera(){if(stream){stopCamera();document.querySelector('#camera-video').classList.add('hidden');document.querySelector('#camera-toggle').innerHTML=icon('camera')+'Ativar câmera';document.querySelector('#camera-badge').textContent='CÂMERA DESLIGADA';document.querySelector('#capture').disabled=true;return}try{if(!navigator.mediaDevices?.getUserMedia)throw Error('A câmera exige HTTPS ou localhost.');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});const v=document.querySelector('#camera-video');if(!v){stopCamera();return}v.srcObject=stream;v.classList.remove('hidden');document.querySelector('#camera-toggle').textContent='Desligar câmera';document.querySelector('#camera-badge').textContent='PRÉVIA LOCAL · SEM ÁUDIO';document.querySelector('#capture').disabled=!activeSession;toast('Câmera ativada. A prévia fica neste navegador.')}catch(e){toast('Não foi possível abrir a câmera: '+e.message)}}
async function createSession(){
  if(recording)return toast('Aguarde o fim da captura.');
  if(!connected){goto('settings');toast('Conecte a API para criar uma sessão real.');return}
  const subject=document.querySelector('#verify-subject');
  const consent=document.querySelector('#verify-consent');
  if(!consent.checked)return toast('Confirme a autorização para capturar a biometria.');
  const button=document.querySelector('#create-session');
  const generation=++sessionGeneration, requestedSubject=subject.value;
  activeSession=null;button.disabled=true;subject.disabled=true;consent.disabled=true;
  document.querySelector('#capture').disabled=true;
  try{
    const result=await request('/api/v1/sessions','POST',{subject_id:requestedSubject,consent:true});
    if(generation!==sessionGeneration||route!=='verify'||!button.isConnected||subject.value!==requestedSubject||!consent.checked)return;
    activeSession=result;
    document.querySelector('#session-status').textContent='Sessão criada. Grave antes de expirar em 120 segundos.';
    const actions=(activeSession.challenge||[]).map(x=>({center:'Olhe ao centro',turn_left:'Vire para a esquerda',turn_right:'Vire para a direita'}[x]||x));
    document.querySelector('#camera-instruction').textContent=actions.join(' → ')||'Siga as instruções de captura';
    document.querySelector('#capture').disabled=!stream;
    document.querySelectorAll('.step')[1].classList.add('active');
    toast('Sessão criada. Siga o desafio indicado.');
  }catch(e){if(button.isConnected&&generation===sessionGeneration){document.querySelector('#session-status').textContent=e.message;activeSession=null}}
  finally{if(button.isConnected){button.disabled=false;subject.disabled=false;consent.disabled=false}}
}
async function capture(){if(recording||!stream||!activeSession)return;if(Date.now()/1000>activeSession.expires_at)return toast('Sessão expirada. Crie uma nova sessão.');if(typeof MediaRecorder==='undefined')return toast('Este navegador não suporta gravação. Use Chrome ou Edge atualizados.');const mime=['video/webm;codecs=vp8','video/webm','video/mp4'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime)return toast('Nenhum formato de vídeo suportado.');const captureSession={...activeSession};recording=true;document.querySelector('#verify-subject').disabled=true;document.querySelector('#verify-consent').disabled=true;const b=document.querySelector('#capture');b.disabled=true;b.textContent='Gravando… 5 s';try{const chunks=[];const blob=await new Promise((resolve,reject)=>{const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:650000});recorder.ondataavailable=e=>chunks.push(e.data);recorder.onerror=()=>reject(Error('Falha ao gravar.'));recorder.onstop=()=>resolve(new Blob(chunks,{type:mime.split(';')[0]}));recorder.start();setTimeout(()=>{if(recorder.state!=='inactive')recorder.stop()},5000)});if(route!=='verify'||activeSession?.session_id!==captureSession.session_id)throw Error('Captura cancelada. Crie uma nova sessão.');b.textContent='Analisando…';const fd=new FormData();fd.append('nonce',activeSession.nonce);fd.append('video',blob,mime.includes('mp4')?'capture.mp4':'capture.webm');const result=await request('/api/v1/sessions/'+activeSession.session_id+'/verify','POST',fd);const messages={approved:['Identidade aprovada','A comparação e a prova de vida foram aprovadas.'],review_required:['Revisão humana necessária','A comparação passou pelo limiar e o desafio foi concluído. O motor é experimental: encaminhe para validação humana. Nenhum registro de ponto foi criado.'],liveness_failed:['Desafio de prova de vida não concluído','A captura não cumpriu as condições do desafio. Crie uma nova sessão e siga a sequência de movimentos.'],face_mismatch:['O rosto não corresponde à referência','Confira o identificador e a imagem de referência. Crie uma nova sessão para tentar novamente.']};const message=messages[result.decision]||['Resultado não reconhecido','Consulte os detalhes técnicos antes de continuar.'];showResult(message[0],message[1],['liveness_failed','face_mismatch'].includes(result.decision),result);document.querySelectorAll('.step').forEach(x=>x.classList.add('active'));activeSession=null;}catch(e){showResult('Não foi possível verificar',e.message,true);activeSession=null}finally{recording=false;if(b.isConnected){document.querySelector('#verify-subject').disabled=false;document.querySelector('#verify-consent').disabled=false;b.textContent='Gravar e verificar';b.disabled=true}}}
async function connect(e){e.preventDefault();const form=e.currentTarget;const candidate=form.elements.namedItem('base').value.replace(/\/$/,'');const key=form.elements.namedItem('token').value;const out=document.querySelector('#connection-result');const button=form.querySelector('button');button.disabled=true;out.textContent='Testando conexão e autenticação…';try{const parsed=new URL(candidate);if(!['https:','http:'].includes(parsed.protocol)|| (parsed.protocol==='http:'&&!['localhost','127.0.0.1'].includes(parsed.hostname)))throw Error('Use HTTPS, ou localhost para desenvolvimento.');const res=await fetch(candidate+'/api/v1/events',{headers:{Authorization:'Bearer '+key}});if(!res.ok)throw Error('A API recusou a conexão. Confira URL, chave e CORS.');await res.json();const health=await fetch(candidate+'/api/v1/health').then(r=>r.json());if(base!==candidate){identities=sample.map(x=>({id:x.subject,name:x.name,initials:x.initials}));records=[...sample];activeSession=null;}base=candidate;token=key;connected=true;out.textContent=`Conectado · motor facial: ${health.face_engine} · liveness: ${health.liveness}`;toast('API conectada. Credenciais mantidas apenas nesta aba.')}catch(err){out.textContent=err.message;out.classList.add('error-text')}finally{button.disabled=false}}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-route]');if(nav)goto(nav.dataset.route);const ep=e.target.closest('[data-endpoint]');if(ep){endpoint=+ep.dataset.endpoint;render()}const detail=e.target.closest('[data-detail]');if(detail){const r=records.find(x=>x.id===detail.dataset.detail);toast(`${r.id} · ${r.subject} · ${r.status} · ${r.ms} ms ${r.source==='api'?'· evento da API':'· exemplo sintético'}`)}const remove=e.target.closest('[data-remove]');if(remove){const id=remove.dataset.remove;const item=identities.find(x=>x.id===id);if(item?.real){if(!connected||item.backend!==base)return toast('Reconecte o backend original desta referência.');if(!confirm('Excluir permanentemente esta referência e seus eventos?'))return;try{await request('/api/v1/subjects/'+encodeURIComponent(id),'DELETE')}catch(err){return toast(err.message)}}identities=identities.filter(x=>x.id!==id);render();toast('Referência excluída.')}});
document.querySelector('#identity-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const id=f.elements.namedItem('id').value;if(identities.some(x=>x.id===id))return toast('Este identificador já está cadastrado.');const b=f.querySelector('button[type=submit]');b.disabled=true;try{if(connected){if(!f.elements.namedItem('reference').files.length)throw Error('Selecione uma imagem de referência.');const fd=new FormData();fd.append('subject_id',id);fd.append('consent','true');fd.append('reference',f.elements.namedItem('reference').files[0]);await request('/api/v1/subjects','POST',fd)}identities.unshift({id,name:f.elements.namedItem('name').value,initials:f.elements.namedItem('name').value.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase(),real:connected,backend:connected?base:null});document.querySelector('#identity-dialog').close();f.reset();render();toast(connected?'Referência cadastrada na API.':'Identidade adicionada à demonstração.')}catch(err){toast(err.message)}finally{b.disabled=false}});
document.querySelector('#close-dialog').onclick=()=>document.querySelector('#identity-dialog').close();document.querySelector('#help').innerHTML=icon('help',18);document.querySelector('#help').onclick=()=>goto('api');window.addEventListener('hashchange',render);window.addEventListener('pagehide',stopCamera);render();
